#!/usr/bin/env node
// scripts/update-coordinates.mjs
//
// Both journey files (public/mapbase/journeys/*.json, generated by
// build-journeys.mjs) and every chapter's [[label|url]] map-overall tags
// (src/data/sgz/*.json) freeze a town's lat/lng at the moment they were
// created. If a town's actual coordinates are later corrected in
// All_Towns.json, those frozen copies silently go stale — the map still
// flies to the old point, but the exact-coordinate match used to look up
// the town record (for opening its detail card, or coloring a journey
// entry by kingdom) fails to find anything, since it never falls back to
// matching by name alone. This script re-syncs both kinds of frozen
// coordinates against the CURRENT All_Towns.json.
//
// For every frozen town reference found:
//   - name doesn't match anything in the current database at all
//       -> flagged as "not found", left untouched
//   - name matches one or more towns (homonyms across different
//     commanderies are matched by name alone, so there can be several),
//     but even the CLOSEST of those candidates is further from the old
//     coordinates than MAX_SHIFT_KM
//       -> flagged as "too far", left untouched (this is more likely a
//          same-named town in a completely different place than a
//          legitimate small correction, and shouldn't be auto-applied)
//   - name matches, and the closest candidate is within MAX_SHIFT_KM
//       -> coordinates updated in place to that candidate's current
//          lat/lng (only touched if they actually differ)
//
// Nothing is EVER auto-applied for a "not found" or "too far" case —
// those are always left as-is and reported for manual review.
//
// Usage (run from the project root, i.e. the "web" folder):
//   node scripts/update-coordinates.mjs           (writes changes)
//   node scripts/update-coordinates.mjs --dry-run (report only, no writes)

import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const TOWNS_PATH = path.join(ROOT, 'public/mapbase/All_Towns.json');
const JOURNEYS_DIR = path.join(ROOT, 'public/mapbase/journeys');
const SGZ_DIR = path.join(ROOT, 'src/data/sgz');

// How far a name-matched candidate is allowed to be from the frozen
// coordinates before it's treated as "probably a different town with the
// same name" rather than "the same town, corrected a little" and gets
// auto-applied. Bump this up if legitimate corrections keep getting
// flagged, or lower it if unrelated same-named towns are slipping through.
const MAX_SHIFT_KM = 50;

const DRY_RUN = process.argv.includes('--dry-run');

function readJson(p) {
  return JSON.parse(fs.readFileSync(p, 'utf-8'));
}
function writeJson(p, data) {
  fs.writeFileSync(p, JSON.stringify(data, null, 2) + '\n', 'utf-8');
}

function distanceKm(lat1, lng1, lat2, lng2) {
  const R = 6371;
  const toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// Every name variant (EN/CH/CHS) maps to the same list of candidate town
// records that carry it, so a frozen reference's name — whichever
// language it happens to be in — resolves against all of them.
function buildNameIndex(towns) {
  const byName = new Map();
  for (const t of towns) {
    for (const n of [t.Town_EN, t.Town_CH, t.Town_CHS]) {
      if (!n) continue;
      const key = String(n).trim().toLowerCase();
      if (!byName.has(key)) byName.set(key, []);
      byName.get(key).push(t);
    }
  }
  return byName;
}

// Central decision function shared by both the journey-file pass and the
// chapter-tag pass, so "not found" / "too far" / "updated" are decided
// identically regardless of which kind of file the reference came from.
//
// zhCandidates (optional): the Chinese name(s) paired with this exact
// reference - a chapter tag's en/zht/zhs versions are positionally
// aligned within the same passage, and a journey stop's resolvedLocations
// entry lines up 1:1 with its own location's {en,zht,zhs}, so where
// available this is real linguistic confirmation of which specific town
// is meant, not just "closest point that happens to share the English
// romanization." Many towns share a romanization, but essentially never
// share the same actual Chinese characters too, so this narrows the
// candidate pool BEFORE distance is used to pick among (or validate)
// what's left, rather than distance being the only signal available.
function resolveCoordUpdate(byName, name, oldLat, oldLng, stats, context, zhCandidates = []) {
  if (!name) {
    stats.noName.push(context);
    return null;
  }

  let candidates = byName.get(String(name).trim().toLowerCase()) || [];

  if (!candidates.length) {
    stats.notFound.push({ ...context, name });
    return null;
  }

  const zhSet = new Set(zhCandidates.filter(Boolean).map((z) => String(z).trim()));
  if (zhSet.size) {
    const zhMatched = candidates.filter((t) => zhSet.has(String(t.Town_CH || '').trim()) || zhSet.has(String(t.Town_CHS || '').trim()));
    // Only narrow down if the Chinese name actually matched something -
    // if it matched nothing (a character variant, OCR difference, etc.)
    // fall back to the full EN-name candidate pool rather than treating
    // "found nothing" as "there are no candidates at all."
    if (zhMatched.length) candidates = zhMatched;
  }

  const withCoords = candidates
    .map((t) => ({ lat: Number(t.Latitude), lng: Number(t.Longitude) }))
    .filter((c) => Number.isFinite(c.lat) && Number.isFinite(c.lng));

  if (!withCoords.length) {
    stats.notFound.push({ ...context, name });
    return null;
  }

  let best = null;
  let bestDist = Infinity;
  for (const c of withCoords) {
    const d = distanceKm(oldLat, oldLng, c.lat, c.lng);
    if (d < bestDist) {
      bestDist = d;
      best = c;
    }
  }

  if (bestDist > MAX_SHIFT_KM) {
    stats.tooFar.push({
      ...context,
      name,
      oldLat,
      oldLng,
      newLat: best.lat,
      newLng: best.lng,
      distanceKm: Number(bestDist.toFixed(1)),
    });
    return null;
  }

  if (bestDist > 1e-9) {
    stats.updated.push({
      ...context,
      name,
      oldLat,
      oldLng,
      newLat: best.lat,
      newLng: best.lng,
      distanceKm: Number(bestDist.toFixed(3)),
      matchedByChineseName: zhSet.size > 0 && candidates.length < (byName.get(String(name).trim().toLowerCase()) || []).length,
    });
    return best;
  }

  return null; // already matches current data exactly, nothing to do
}

function newStats() {
  return { updated: [], notFound: [], tooFar: [], noName: [] };
}

// ── Journey files ──────────────────────────────────────────────────────
// Two separate places carry the same kind of town entry within one
// journey JSON: the deduplicated top-level `pins` list, and each stop's
// own `resolvedLocations` (what the frontend actually reads for
// click-through and kingdom-coloring on the journey panel). Only the
// latter has a paired Chinese name available - build-journeys.mjs never
// deletes a stop's original `location` ({en,zht,zhs}, or an array of
// those) after adding `resolvedLocations` alongside it, and the two stay
// index-aligned 1:1. `pins` is just a deduplicated view across every
// stop's resolvedLocations, so rather than re-resolving each pin
// independently (which could pick a different, less-informed answer for
// the same real-world place), stops are processed first and the exact
// same resolution gets applied to any pin sharing that old coordinate.
function oldCoordKey(lat, lng) {
  return `${lat}:${lng}`;
}

function updateTownEntry(entry, byName, stats, context, zhCandidates = [], fallbackName = '') {
  if (!entry || entry.kind !== 'town') return null;
  const lat = Number(entry.lat);
  const lng = Number(entry.lng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;

  // entry.name comes from the url's own name= param, which is optional
  // and often just isn't set - the paired location's own {en} name (its
  // display label) is a good fallback, same reasoning as the tag-label
  // fallback used for chapter text.
  const resolveName = entry.name || fallbackName;
  const updated = resolveCoordUpdate(byName, resolveName, lat, lng, stats, context, zhCandidates);
  if (!updated) return null;

  const oldKey = oldCoordKey(lat, lng);
  entry.lat = updated.lat;
  entry.lng = updated.lng;
  return { oldKey, newLat: updated.lat, newLng: updated.lng };
}

function processJourneyFiles(byName) {
  const stats = newStats();
  if (!fs.existsSync(JOURNEYS_DIR)) {
    console.warn(`  ! ${JOURNEYS_DIR} not found — skipping journey files`);
    return stats;
  }

  const files = fs.readdirSync(JOURNEYS_DIR).filter((f) => f.endsWith('.json'));
  let filesChanged = 0;

  for (const file of files) {
    const filePath = path.join(JOURNEYS_DIR, file);
    const data = readJson(filePath);
    const before = JSON.stringify(data);

    // Map of "oldLat:oldLng" -> resolved {newLat,newLng}, built while
    // processing stops below, then reused for pins so both stay in sync.
    const resolvedByOldCoord = new Map();

    for (const person of data.journeyOverviews ?? []) {
      for (const stop of person.stops ?? []) {
        const rawLocations = Array.isArray(stop.location) ? stop.location : stop.location ? [stop.location] : [];
        const resolvedLocations = stop.resolvedLocations ?? [];

        resolvedLocations.forEach((entry, i) => {
          const pairedName = rawLocations[i];
          const zhCandidates = pairedName ? [pairedName.zht, pairedName.zhs] : [];
          const result = updateTownEntry(entry, byName, stats, { file, where: `stop (${person.person || '?'})` }, zhCandidates, pairedName?.en || '');
          if (result) resolvedByOldCoord.set(result.oldKey, result);
        });
      }
    }

    for (const pin of data.pins ?? []) {
      if (!pin || pin.kind !== 'town') continue;
      const lat = Number(pin.lat);
      const lng = Number(pin.lng);
      if (!Number.isFinite(lat) || !Number.isFinite(lng)) continue;

      const already = resolvedByOldCoord.get(oldCoordKey(lat, lng));
      if (already) {
        pin.lat = already.newLat;
        pin.lng = already.newLng;
      } else {
        // Didn't match any processed stop's old coordinate (shouldn't
        // normally happen, since pins are derived from stops - falls
        // back to a plain name+distance resolution just in case, with no
        // paired Chinese name available for this standalone case).
        updateTownEntry(pin, byName, stats, { file, where: 'pins' });
      }
    }

    if (JSON.stringify(data) !== before) {
      filesChanged++;
      if (!DRY_RUN) writeJson(filePath, data);
    }
  }

  console.log(`Journey files: ${filesChanged} file(s) ${DRY_RUN ? 'would be' : 'were'} changed, out of ${files.length} scanned.`);
  return stats;
}

// ── Chapter [[label|url]] tags ─────────────────────────────────────────
// A tag's url can carry a /zh-hant or /zh-hans prefix ahead of the actual
// path — preserved exactly as-is, only the lat/lng query params
// themselves get rewritten, everything else about the url (prefix, name
// param, any other params) stays untouched.
function stripLangPrefix(rawUrl) {
  return rawUrl.replace(/^\/zh-han[st]/, '');
}

function parseMapOverallLatLng(rawUrl) {
  const stripped = stripLangPrefix(rawUrl);
  if (!stripped.includes('/maps/map-overall')) return null;
  let parsed;
  try {
    parsed = new URL(stripped, 'http://x');
  } catch {
    return null;
  }

  // admin=/water= links point to a commandery, province, or river by a
  // stable ID, not by a frozen coordinate - the ID keeps working
  // correctly regardless of where that feature's geometry is redrawn, so
  // these links were never at risk from a coordinate shift in the first
  // place and this script has nothing to do for them. Must be checked
  // BEFORE attempting lat/lng: a link with neither param has
  // searchParams.get('lat') return null, and Number(null) === 0 in
  // JavaScript (not NaN) - so without this check, an admin/water link
  // was being silently misread as a "valid" (0,0) coordinate, which then
  // got flagged thousands of km "too far" from every real match.
  if (parsed.searchParams.has('admin') || parsed.searchParams.has('water')) return null;

  if (!parsed.searchParams.has('lat') || !parsed.searchParams.has('lng')) return null;
  const lat = Number(parsed.searchParams.get('lat'));
  const lng = Number(parsed.searchParams.get('lng'));
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return { lat, lng, name: parsed.searchParams.get('name') || '' };
}

function rewriteUrlCoords(rawUrl, newLat, newLng) {
  const prefixMatch = rawUrl.match(/^\/zh-han[st]/);
  const prefix = prefixMatch ? prefixMatch[0] : '';
  const stripped = stripLangPrefix(rawUrl);
  const parsed = new URL(stripped, 'http://x');
  parsed.searchParams.set('lat', String(newLat));
  parsed.searchParams.set('lng', String(newLng));
  return prefix + parsed.pathname + parsed.search;
}

const TAG_RE = /\[\[([^|\]]+)\|([^\]]+)\]\]/g;

function extractTags(text) {
  if (typeof text !== 'string') return [];
  const tags = [];
  let m;
  TAG_RE.lastIndex = 0;
  while ((m = TAG_RE.exec(text)) !== null) {
    tags.push({ label: m[1], url: m[2] });
  }
  return tags;
}

// Rewrites every location tag within one text field, using a resolved
// {newLat,newLng} lookup keyed by that tag's own position index within
// the field (built by updateTripletTags below, shared across en/zht/zhs
// so all three get the same corrected coordinates for the same place)
// rather than re-resolving independently per language.
function applyResolvedCoordsToText(text, resolvedByIndex) {
  if (typeof text !== 'string' || !text.includes('[[')) return text;
  let i = -1;
  let changed = false;
  const newText = text.replace(TAG_RE, (whole, label, rawUrl) => {
    i++;
    const resolved = resolvedByIndex.get(i);
    if (!resolved) return whole;
    changed = true;
    return `[[${label}|${rewriteUrlCoords(rawUrl, resolved.lat, resolved.lng)}]]`;
  });
  return changed ? newText : text;
}

// Processes one passage/annotation's en+zht+zhs text together (rather
// than each language independently), since within a single passage the
// Nth tag in en corresponds exactly to the Nth tag in zht and zhs - the
// zht/zhs label at that same position is the real Chinese name for
// whatever the en tag's romanization refers to, a much stronger
// disambiguation signal than distance alone when multiple towns happen
// to share an English romanization. Returns the (possibly rewritten)
// {en, zht, zhs} texts.
function updateTripletTags(enText, zhtText, zhsText, byName, stats, context) {
  const enTags = extractTags(enText);
  const zhtTags = extractTags(zhtText);
  const zhsTags = extractTags(zhsText);
  const maxLen = Math.max(enTags.length, zhtTags.length, zhsTags.length);

  // Resolved {lat,lng} per position index, shared across all three texts
  // so the same tag position in every language gets the identical
  // corrected coordinate.
  const resolvedByIndex = new Map();

  for (let i = 0; i < maxLen; i++) {
    // Prefer the en tag's own url as the "primary" one to resolve from
    // (matches the existing convention elsewhere - name params are
    // stored in English), falling back to whichever of zht/zhs actually
    // has a parseable map link at this position if en doesn't.
    const candidates = [enTags[i], zhtTags[i], zhsTags[i]].filter(Boolean);
    let primary = null;
    let primaryLoc = null;
    for (const c of candidates) {
      const loc = parseMapOverallLatLng(c.url);
      if (loc) {
        primary = c;
        primaryLoc = loc;
        break;
      }
    }
    if (!primary) continue;

    // The URL's own name= param is optional and often just isn't there -
    // parseLocationEntry has always treated it as optional, and the map
    // itself works fine without it (it just flies to the coordinate
    // regardless). But the tag's own label text is almost always the
    // actual place name anyway, just not repeated in the query string -
    // so it's a good fallback rather than treating "no name param" as
    // "no name available at all."
    const resolveName = primaryLoc.name || primary.label;

    const zhCandidates = [zhtTags[i]?.label, zhsTags[i]?.label];
    const updated = resolveCoordUpdate(byName, resolveName, primaryLoc.lat, primaryLoc.lng, stats, {
      ...context,
      label: primary.label,
    }, zhCandidates);

    if (updated) resolvedByIndex.set(i, updated);
  }

  if (!resolvedByIndex.size) return { en: enText, zht: zhtText, zhs: zhsText };

  return {
    en: applyResolvedCoordsToText(enText, resolvedByIndex),
    zht: applyResolvedCoordsToText(zhtText, resolvedByIndex),
    zhs: applyResolvedCoordsToText(zhsText, resolvedByIndex),
  };
}

function processChapterFiles(byName) {
  const stats = newStats();
  if (!fs.existsSync(SGZ_DIR)) {
    console.warn(`  ! ${SGZ_DIR} not found — skipping chapter files`);
    return stats;
  }

  const files = fs.readdirSync(SGZ_DIR).filter((f) => f.endsWith('.json'));
  let filesChanged = 0;

  for (const file of files) {
    const filePath = path.join(SGZ_DIR, file);
    const data = readJson(filePath);
    const before = JSON.stringify(data);
    const chapterId = data.id || path.basename(file, '.json');

    for (const passage of data.passages ?? []) {
      const context = { file, chapter: chapterId, passageId: passage.id };

      const mainResult = updateTripletTags(passage.en, passage.orig?.zht, passage.orig?.zhs, byName, stats, context);
      passage.en = mainResult.en;
      if (passage.orig) {
        passage.orig.zht = mainResult.zht;
        passage.orig.zhs = mainResult.zhs;
      }

      for (const a of passage.annotations ?? []) {
        const annoResult = updateTripletTags(a.en, a.zht, a.zhs, byName, stats, context);
        a.en = annoResult.en;
        a.zht = annoResult.zht;
        a.zhs = annoResult.zhs;
      }
    }

    if (JSON.stringify(data) !== before) {
      filesChanged++;
      if (!DRY_RUN) writeJson(filePath, data);
    }
  }

  console.log(`Chapter files: ${filesChanged} file(s) ${DRY_RUN ? 'would be' : 'were'} changed, out of ${files.length} scanned.`);
  return stats;
}

function mergeStats(a, b) {
  return {
    updated: [...a.updated, ...b.updated],
    notFound: [...a.notFound, ...b.notFound],
    tooFar: [...a.tooFar, ...b.tooFar],
    noName: [...a.noName, ...b.noName],
  };
}

function printReport(stats) {
  console.log(`\n${DRY_RUN ? '[DRY RUN] ' : ''}Summary:`);
  console.log(`  Updated:   ${stats.updated.length}`);
  console.log(`  Not found: ${stats.notFound.length}`);
  console.log(`  Too far:   ${stats.tooFar.length} (> ${MAX_SHIFT_KM} km — left untouched, needs manual review)`);
  console.log(`  No name:   ${stats.noName.length} (a lat/lng entry with no name to match against at all)`);

  if (stats.notFound.length) {
    console.log(`\n! Could not find a current town matching these names — left untouched:`);
    for (const r of stats.notFound) console.log(`    "${r.name}" — ${r.file}${r.chapter ? ` (${r.chapter}${r.passageId ? `, passage ${r.passageId}` : ''})` : r.where ? ` (${r.where})` : ''}`);
  }

  if (stats.tooFar.length) {
    console.log(`\n! Closest name match was further than ${MAX_SHIFT_KM} km away — left untouched, please review manually:`);
    for (const r of stats.tooFar) {
      console.log(
        `    "${r.name}" — ${r.file}${r.chapter ? ` (${r.chapter}${r.passageId ? `, passage ${r.passageId}` : ''})` : r.where ? ` (${r.where})` : ''}: ` +
          `(${r.oldLat}, ${r.oldLng}) -> closest match (${r.newLat}, ${r.newLng}), ${r.distanceKm} km away`
      );
    }
  }

  if (stats.noName.length) {
    console.log(`\n! Entries with coordinates but no name to match against (can't safely resolve without one):`);
    for (const r of stats.noName) console.log(`    ${r.file}${r.chapter ? ` (${r.chapter}${r.passageId ? `, passage ${r.passageId}` : ''})` : r.where ? ` (${r.where})` : ''}`);
  }

  if (stats.updated.length) {
    console.log(`\nUpdated (small shifts, auto-applied):`);
    for (const r of stats.updated) {
      console.log(`    "${r.name}" — ${r.file}: (${r.oldLat}, ${r.oldLng}) -> (${r.newLat}, ${r.newLng}), ${r.distanceKm} km`);
    }
  }
}

function main() {
  if (!fs.existsSync(TOWNS_PATH)) {
    console.error(`ERROR: ${TOWNS_PATH} not found. Run this from the project root.`);
    process.exit(1);
  }

  const townsData = readJson(TOWNS_PATH);
  const towns = townsData.All_Towns_Details ?? townsData ?? [];
  const byName = buildNameIndex(towns);
  console.log(`Loaded ${towns.length} towns from All_Towns.json.${DRY_RUN ? ' (dry run — no files will be written)' : ''}\n`);

  const journeyStats = processJourneyFiles(byName);
  const chapterStats = processChapterFiles(byName);
  const combined = mergeStats(journeyStats, chapterStats);

  printReport(combined);
}

main();
